  env: { fogNear: 60, fogFar: 320, ambient: 0.42 },

  // WHERE THE WATER ENDS, as a contour of the blurred terrain field, and
  // the one place that decides it. The client draws its shoreline here and
  // the server decides swimming here, so the two cannot drift apart -- they
  // did, and the gap between them was 766 cells of dry ground you swam in.
  // The levels are measured: these two contours reproduce the areas the
  // blueprint draws (5.6% deep, 7.2% wetted) to within a tenth of a point.
  // `fade` is the level by which the LAND has faded out entirely. It makes
  // "ground under the waterline" and "inside the drawn edge" the same test,
  // so the drawn shore and the swimming rule cannot come apart.
  waterEdge: { deep: 0.41, marsh: 0.44, fade: 0.41, blur: 3 },

  // Rock: how tall the client draws it, and how steep is too steep to
  // walk. One pair of numbers for one cliff -- the client draws by
  // the field; the server stops you where that surface is steeper than
  // walkSlope (40 degrees). A road is the one exception: see rockSolidAt.
  rockEdge: { rise: 17.0, walkSlope: 0.84 },

